    const ts = new Date(Date.now() + TAIPEI_OFFSET_MS).toISOString().replace("Z", "+08:00");
    fs.appendFileSync(LOG_PATH, `[${ts}] ${line}\n`);
  } catch (_) {
    // logging must never crash the hook
  }
}

