"use strict";

// OpenClaw Hook：bni-reminder-schedule
// 用途：LINE三個帳號（bni_tainan/jiaolian_thoughts/default龍蝦小助教）共用的
//       「主動提醒」功能（v77設計，2026-07-30實作bni_tainan，2026-08-03推廣到
//       全部三個帳號）。agent本身沒有exec/cron工具（教練指示鎖死系統層權限給
//       非教練發送者，見openclaw.json tools.toolsBySender），所以無法自己呼叫
//       `openclaw cron add`。改由這支hook在伺服器端（Node.js，不受工具權限限制）
//       解析用戶訊息裡的時間+提醒內容，直接排一次性cron，agent只需要照AGENTS.md
//       指示自然回覆確認即可，完全不需要拿到任何工具權限。
// 事件：message:preprocessed（跟line-user-memory/knowledge-search-inject同一個
//       事件，在LLM看到訊息前執行，可以拿到用戶原始文字）
// 軍師建立 2026-07-30（教練：還沒做就去做，發現v83權限鎖擋住v77設計後，教練選擇
//       伺服器端hook代勞方案，不開放cron工具給會員）
// 2026-08-03 推廣：教練指示「立刻推廣到三個帳號」，改成任何LINE帳號的
//       agent:<accountId>:line:direct:<userId> session都會觸發，不再只認
//       bni_tainan。每個用戶各自獨立排程，互不影響。

const { execFile } = require("child_process");
const fs = require("fs");
const path = require("path");

const OPENCLAW_BIN = "/opt/homebrew/bin/openclaw";
const SEND_SCRIPT = "/Users/bymyway/.openclaw/agents/bni_tainan/scripts/send_line_push.py";
const LOG_PATH = "/Users/bymyway/.openclaw/agents/bni_tainan/scripts/reminder_hook.log";
const TAIPEI_OFFSET_MS = 8 * 60 * 60 * 1000;
const MAX_FUTURE_DAYS = 90;
const SUPPORTED_ACCOUNTS = new Set(["bni_tainan", "jiaolian_thoughts", "default"]);

function log(line) {
  try {
    const ts = new Date(Date.now() + TAIPEI_OFFSET_MS).toISOString().replace("Z", "+08:00");
    fs.appendFileSync(LOG_PATH, `[${ts}] ${line}\n`);
  } catch (_) {
    // logging must never crash the hook
  }
}

function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    c.bodyForAgent,
    event.text,
    c.text,
    c.content,
  ];
  for (const v of cands) if (typeof v === "string" && v.trim()) return v.trim();
  return "";
}

function parseSession(event) {
  const sessionKey = String(event.sessionKey ?? (event.context && event.context.sessionKey) ?? "");
  // 格式：agent:<accountId>:line:direct:<userId>
  const parts = sessionKey.split(":");
  const agentIdx = parts.indexOf("agent");
  const accountId = agentIdx >= 0 && parts[agentIdx + 1] ? parts[agentIdx + 1] : null;
  if (!accountId) return null;

  let userId = String(event.from ?? (event.context && event.context.from) ?? "");
  if (userId.startsWith("line:")) userId = userId.slice("line:".length);
  if (!userId) userId = parts[parts.length - 1] || "";
  if (!userId) return null;

  return { accountId, userId, sessionKey };
}

// --- 中文時間解析（保守設計：抓不準就放棄，不亂猜）---

function taipeiNowParts() {
  const utcMs = Date.now();
  const d = new Date(utcMs + TAIPEI_OFFSET_MS);
  return {
    year: d.getUTCFullYear(),
    month: d.getUTCMonth(),
    day: d.getUTCDate(),
    hour: d.getUTCHours(),
    minute: d.getUTCMinutes(),
    utcMs,
  };
}

function taipeiWallToUtcMs(year, month, day, hour, minute) {
  const wallAsUtcMs = Date.UTC(year, month, day, hour, minute, 0);
  return wallAsUtcMs - TAIPEI_OFFSET_MS;
}

// 相對時間："30分鐘後" "2小時後" "1天後"
function parseRelative(text, nowUtcMs) {
  const m = text.match(/(\d+)\s*(分鐘|分|小時|鐘頭|天)\s*後/);
  if (!m) return null;
  const n = parseInt(m[1], 10);
  if (!Number.isFinite(n) || n <= 0) return null;
  const unit = m[2];
  let ms;
  if (unit === "分鐘" || unit === "分") ms = n * 60 * 1000;
  else if (unit === "小時" || unit === "鐘頭") ms = n * 60 * 60 * 1000;
  else if (unit === "天") ms = n * 24 * 60 * 60 * 1000;
  else return null;
  return { targetUtcMs: nowUtcMs + ms, matchedText: m[0] };
}

// 絕對時間："明天下午三點" "今天晚上8點30分" "後天早上9點"
const CN_NUM = { 零:0, 一:1, 二:2, 兩:2, 三:3, 四:4, 五:5, 六:6, 七:7, 八:8, 九:9, 十:10 };
function cnNumToInt(s) {
  if (/^\d+$/.test(s)) return parseInt(s, 10);
  if (s === "十") return 10;
  if (s.length === 2 && s[0] === "十") return 10 + (CN_NUM[s[1]] ?? 0);
  if (s.length === 2 && s[1] === "十") return (CN_NUM[s[0]] ?? 0) * 10;
  if (s.length === 3 && s[1] === "十") return (CN_NUM[s[0]] ?? 0) * 10 + (CN_NUM[s[2]] ?? 0);
  return CN_NUM[s] ?? NaN;
}

function parseAbsolute(text, nowParts) {
  const hourNumPattern = "(\\d{1,2}|[零一二兩三四五六七八九十]{1,3})";
  const re = new RegExp(
    "(今天|今日|明天|明日|後天)?\\s*(凌晨|早上|上午|中午|下午|晚上|傍晚)?\\s*" +
      hourNumPattern + "\\s*[點点]\\s*(半|" + hourNumPattern.replace("(", "(?:") + "分?)?",
  );
  const m = text.match(re);
  if (!m) return null;

  const dayWord = m[1] || null;
  const periodWord = m[2] || null;
  let hour = cnNumToInt(m[3]);
  if (!Number.isFinite(hour) || hour < 0 || hour > 23) return null;
  // 沒有上午/下午等字眼、時數又落在1~12之間 -> 真假難辨（早上還是晚上？），
  // 寧可放棄不猜，避免記錯十二小時
  if (!m[2] && hour >= 1 && hour <= 12) return null;

  let minute = 0;
  if (m[4]) {
    if (m[4] === "半") minute = 30;
    else {
      const mm = cnNumToInt(m[4].replace("分", ""));
      if (Number.isFinite(mm) && mm >= 0 && mm < 60) minute = mm;
    }
  }

  if (periodWord) {
    if (/下午|晚上|傍晚/.test(periodWord)) {
      if (hour < 12) hour += 12;
    } else if (/早上|上午/.test(periodWord)) {
      if (hour === 12) hour = 0;
    } else if (/中午/.test(periodWord)) {
      if (hour !== 12) hour = 12;
    }
    // 凌晨：hour 照給定值即可
  }

  let dayOffset = 0;
  if (dayWord) {
    if (/後天/.test(dayWord)) dayOffset = 2;
    else if (/明天|明日/.test(dayWord)) dayOffset = 1;
    else dayOffset = 0;
  }

  let targetDay = nowParts.day + dayOffset;
  let targetUtcMs = taipeiWallToUtcMs(nowParts.year, nowParts.month, targetDay, hour, minute);

  // 沒有明確指定日期詞，且算出來的時間已經過了 -> 順延到明天（避免叫使用者「回到過去」）
  if (!dayWord && targetUtcMs <= nowParts.utcMs) {
    targetUtcMs = taipeiWallToUtcMs(nowParts.year, nowParts.month, nowParts.day + 1, hour, minute);
  }

  return { targetUtcMs, matchedText: m[0] };
}

function extractReminderContent(rawText, matchedTimeText) {
  let s = rawText;
  if (matchedTimeText) s = s.split(matchedTimeText).join(" ");
  s = s.replace(/提醒我|提醒一下我|麻煩提醒我|請提醒我|幫我提醒|提醒/g, " ");
  s = s.replace(/[，,。、\s]+/g, " ").trim();
  s = s.replace(/^(要|去|說|去要)+/, "").trim();
  return s || rawText.trim();
}

function buildJobName(userId, targetUtcMs) {
  const last4 = userId.slice(-4);
  return `BNI提醒-${last4}-${targetUtcMs}`;
}

function scheduleReminder({ userId, targetUtcMs, content }) {
  const iso = new Date(targetUtcMs).toISOString();
  const name = buildJobName(userId, targetUtcMs);
  const message = `🔔 提醒您：${content}`;

  if (process.env.BNI_REMINDER_DRY_RUN === "1") {
    log(`DRY-RUN would cron add name=${name} userId=${userId} iso=${iso} content="${content}"`);
    return;
  }

  const argv = [
    "cron",
    "add",
    "--at",
    iso,
    "--delete-after-run",
    "--name",
    name,
    "--command-argv",
    JSON.stringify(["python3", SEND_SCRIPT, "--to", userId, "--message", message]),
  ];

  execFile(OPENCLAW_BIN, argv, { timeout: 15000 }, (err, stdout, stderr) => {
    if (err) {
      log(`FAIL cron add userId=${userId} iso=${iso} err=${err.message} stderr=${stderr}`);
    } else {
      log(`OK cron add name=${name} userId=${userId} iso=${iso} content="${content}"`);
    }
  });

  log(`SCHEDULED name=${name} userId=${userId} iso=${iso} content="${content}"`);
}

const handler = async (event) => {
  try {
    if (!event || event.type !== "message" || event.action !== "preprocessed") return;
    const parsed = parseSession(event);
    if (!parsed || parsed.accountId !== "bni_tainan") return;

    const text = extractText(event);
    if (!text || !/提醒/.test(text)) return;

    const nowParts = taipeiNowParts();
    const rel = parseRelative(text, nowParts.utcMs);
    const abs = rel ? null : parseAbsolute(text, nowParts);
    const hit = rel || abs;
    if (!hit) {
      log(`SKIP unparseable time userId=${parsed.userId} text="${text}"`);
      return;
    }

    const maxFutureMs = nowParts.utcMs + MAX_FUTURE_DAYS * 24 * 60 * 60 * 1000;
    if (hit.targetUtcMs <= nowParts.utcMs + 5000 || hit.targetUtcMs > maxFutureMs) {
      log(`SKIP out-of-range target userId=${parsed.userId} text="${text}" targetUtcMs=${hit.targetUtcMs}`);
      return;
    }

    const content = extractReminderContent(text, hit.matchedText);
    scheduleReminder({ userId: parsed.userId, targetUtcMs: hit.targetUtcMs, content });
  } catch (e) {
    log(`ERROR ${e && e.stack ? e.stack : e}`);
  }
};

module.exports = handler;

